def decode_nested_run_length(s):
    num_stack = []
    str_stack = []
    current = []
    num = 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == '[':
            num_stack.append(num)
            str_stack.append(current)
            num = 0
            current = []
        elif ch == ']':
            repeated = current * num_stack.pop()
            current = str_stack.pop()
            current.extend(repeated)
        else:
            current.append(ch)
    return ''.join(current)

