def sliding_window_maximum(xs, k):
    if not xs or k <= 0 or k > len(xs):
        return []

    from collections import deque

    result = []
    dq = deque()  # holds indices, values decreasing front-to-back

    for i, x in enumerate(xs):
        while dq and xs[dq[-1]] <= x:
            dq.pop()
        dq.append(i)

        if dq[0] <= i - k:
            dq.popleft()

        if i >= k - 1:
            result.append(xs[dq[0]])

    return result

