def vigenere_cipher_encode(s, key):
    result = []
    k = 0
    for ch in s:
        if ch.isalpha():
            shift = ord(key[k % len(key)]) - ord('a')
            base = ord('A') if ch.isupper() else ord('a')
            result.append(chr((ord(ch) - base + shift) % 26 + base))
            k += 1
        else:
            result.append(ch)
    return ''.join(result)

